//! Collecting credentials during setup without them entering a model's context.
//!
//! # The problem
//!
//! A setup flow driven by a model has to ask the user for an API key. The model
//! must know that a key is *needed*, and must be able to hand it to a
//! connection test — but it must never see the key itself. Anything a model
//! sees is in a transcript, and a transcript is stored, sent onward, and
//! sometimes shown to someone else.
//!
//! # How it works
//!
//! The model never handles a value, only a handle to one.
//!
//! 1. The model asks for a secret by name. The vault mints an opaque
//!    [`SecretRef`] — `secret://<hex>` — and parks a waiter against it. The
//!    host prompts the user out of band.
//! 2. The user answers. The host submits the value against the handle, which
//!    wakes the waiter.
//! 3. The model passes the *handle* to a connection test or an install. The
//!    vault resolves handles to values at the last moment, inside the operation
//!    that needs them.
//!
//! The raw value crosses the model-facing surface at no point in that sequence.
//!
//! # Nothing here is persisted
//!
//! The vault is in memory and dies with the process. A value only becomes
//! durable when an install commits it to the credential store, which is the
//! step the user explicitly asked for.
//!
//! # Two lifetimes bound it
//!
//! An unanswered request gives up after [`REQUEST_TIMEOUT`], because a model
//! waiting forever on a prompt the user closed is a hung conversation. An
//! answered-but-unused value is swept after [`IDLE_TTL`], which is long enough
//! for a few connection-test retries and short enough that an abandoned setup
//! does not leave a credential sitting in memory.

mod types;

pub use types::{IDLE_TTL, REQUEST_TIMEOUT, SecretRef, SecretVault};

#[cfg(test)]
mod test;

//! Deciding how a server from a catalog will actually be run.

use serde_json::Value;

use crate::error::{Error, Result};
use tinymcp_bus::{CommandKind, RegistryConnection, RegistryServerDetail, Transport};

/// Normalizes a connection's declared type into the vocabulary installs use.
///
/// Catalogs say `http`; an install record says `http_remote`. Server-sent
/// events are a hosted endpoint too. Mapping them here means one spelling
/// downstream instead of three checks at every site.
#[must_use]
pub(super) fn transport_kind(connection: &RegistryConnection) -> &str {
    match connection.r#type.as_str() {
        "stdio" => "stdio",
        "http" | "http_remote" | "sse" => "http_remote",
        other => other,
    }
}

/// Chooses the connection an install should use.
///
/// # Hosted first
///
/// In order: a published hosted endpoint, any hosted endpoint, a published
/// subprocess package, any subprocess package.
///
/// Most catalog servers offer both. Preferring the subprocess means every
/// install has to find a runtime, resolve a package, and locate credentials on
/// the user's machine — three ways to fail before the server is even reached,
/// and they fail for most community packages. A hosted endpoint removes all
/// three and routes authentication to the server's own challenge, which is
/// something the user can act on.
///
/// The trade is real and deliberate: data goes to the hosted endpoint and a
/// network is required. It favours connecting over running locally.
#[must_use]
pub fn pick_connection(connections: &[RegistryConnection]) -> Option<&RegistryConnection> {
    let published_http = connections
        .iter()
        .find(|connection| transport_kind(connection) == "http_remote" && connection.published);
    if published_http.is_some() {
        return published_http;
    }

    let any_http = connections
        .iter()
        .find(|connection| transport_kind(connection) == "http_remote");
    if any_http.is_some() {
        return any_http;
    }

    let published_stdio = connections
        .iter()
        .find(|connection| transport_kind(connection) == "stdio" && connection.published);
    if published_stdio.is_some() {
        return published_stdio;
    }

    connections
        .iter()
        .find(|connection| transport_kind(connection) == "stdio")
}

/// The credential names an install will actually need.
///
/// Read from the connection [`pick_connection`] chose, not from every
/// connection the catalog listed. A server offering both a hosted endpoint and
/// a subprocess package must not demand the package's environment variables for
/// an install that connects over HTTP and never reads them — that is a form the
/// user cannot complete for a server that would have worked.
#[must_use]
pub fn collect_required_env_keys(detail: &RegistryServerDetail) -> Vec<String> {
    let Some(connection) = pick_connection(&detail.connections) else {
        return Vec::new();
    };

    let Some(properties) = connection
        .config_schema
        .as_ref()
        .and_then(|schema| schema.get("properties"))
        .and_then(Value::as_object)
    else {
        return Vec::new();
    };

    let mut names: Vec<String> = Vec::with_capacity(properties.len());
    for name in properties.keys() {
        if !names.contains(name) {
            names.push(name.clone());
        }
    }
    names
}

/// Works out how an install will be launched, from the chosen connection.
///
/// A hosted install carries its endpoint and no command; a subprocess install
/// carries a command and no endpoint.
///
/// # Errors
///
/// Returns [`Error::MalformedResponse`] when a hosted connection declares no
/// endpoint — there is nothing to dial, and installing it would produce a
/// record that fails on every connect with no way to fix it.
pub fn build_install_transport(
    qualified_name: &str,
    connection: &RegistryConnection,
) -> Result<(Transport, CommandKind, String, Vec<String>)> {
    if transport_kind(connection) == "http_remote" {
        let url = connection.deployment_url.clone().unwrap_or_default();
        if url.trim().is_empty() {
            return Err(Error::malformed(format!(
                "the hosted connection for `{qualified_name}` declares no endpoint"
            )));
        }

        return Ok((
            Transport::HttpRemote { url },
            // Unused for a hosted install; the record still needs a value.
            CommandKind::Node,
            String::new(),
            Vec::new(),
        ));
    }

    let (kind, command, args) = resolve_command(qualified_name, Some(connection));
    Ok((Transport::Stdio, kind, command, args))
}

/// Works out the command a subprocess install is launched with.
///
/// The catalog's worked example when it supplied one, and otherwise `npx -y`
/// against the qualified name — which is how both scoped and plain package
/// names launch.
#[must_use]
pub(super) fn resolve_command(
    qualified_name: &str,
    connection: Option<&RegistryConnection>,
) -> (CommandKind, String, Vec<String>) {
    let example = connection
        .and_then(|connection| connection.example_config.as_ref())
        .and_then(|example| {
            let command = example.get("command").and_then(Value::as_str)?;
            let args = example
                .get("args")
                .and_then(Value::as_array)
                .map(|args| {
                    args.iter()
                        .filter_map(Value::as_str)
                        .map(String::from)
                        .collect()
                })
                .unwrap_or_default();
            Some((command.to_string(), args))
        });

    if let Some((command, args)) = example {
        // The launcher names the ecosystem: `uvx` and `python` are the Python
        // ones, everything else is Node.
        let kind = if command.contains("uvx") || command.contains("python") {
            CommandKind::Python
        } else {
            CommandKind::Node
        };
        return (kind, command, args);
    }

    (
        CommandKind::Node,
        "npx".to_string(),
        vec!["-y".to_string(), qualified_name.to_string()],
    )
}

//! The secret handle and the vault behind it.

use std::collections::HashMap;
use std::time::{Duration, Instant};

use tokio::sync::{Mutex, oneshot};

use crate::error::{Error, Result};

/// How long an unanswered request waits before giving up.
///
/// A model waiting forever on a prompt the user closed is a hung conversation
/// with no way out.
pub const REQUEST_TIMEOUT: Duration = Duration::from_secs(300);

/// How long an answered but unused value survives.
///
/// Long enough for a few connection-test retries; short enough that an
/// abandoned setup does not leave a credential sitting in memory.
pub const IDLE_TTL: Duration = Duration::from_secs(900);

/// The scheme every handle carries.
const SCHEME: &str = "secret://";

/// How many hexadecimal characters a handle holds.
///
/// Forty-eight bits, from a version-4 identifier. Short enough to appear in a
/// log line without cluttering it, and far beyond collision within any setup
/// session — and it does not need to be unguessable, because knowing a handle
/// buys nothing: resolution happens inside the process that minted it.
const HANDLE_LENGTH: usize = 12;

/// An opaque handle to a credential the user supplied.
///
/// This is what a model is given. It carries no part of the value.
#[derive(Debug, Clone, PartialEq, Eq, Hash)]
pub struct SecretRef(String);

impl SecretRef {
    /// The handle as it is written.
    #[must_use]
    pub fn as_str(&self) -> &str {
        &self.0
    }

    /// Reads a handle a caller supplied.
    ///
    /// Accepts the written form and bare hexadecimal alike, since a caller may
    /// pass back either. Anything that is not hexadecimal is refused, so a
    /// model that invents a handle gets a clear rejection rather than a lookup
    /// miss that reads like an expiry.
    ///
    /// # Examples
    ///
    /// ```
    /// # use tinymcp::registry::setup::SecretRef;
    /// assert!(SecretRef::parse("secret://abc123").is_some());
    /// assert!(SecretRef::parse("abc123").is_some());
    /// assert!(SecretRef::parse("not-hex").is_none());
    /// ```
    #[must_use]
    pub fn parse(raw: &str) -> Option<Self> {
        // Trimmed before the scheme is stripped, not after. A caller that pads
        // the handle — which is what a model producing it in prose does — would
        // otherwise fail the prefix match, keep the scheme, and then be
        // rejected for not being hexadecimal.
        let trimmed = raw.trim();
        let hex = trimmed.strip_prefix(SCHEME).unwrap_or(trimmed).trim();

        if hex.is_empty() || !hex.chars().all(|c| c.is_ascii_hexdigit()) {
            return None;
        }

        Some(Self(format!("{SCHEME}{hex}")))
    }

    /// Mints a fresh handle.
    fn mint() -> Self {
        let raw = uuid::Uuid::new_v4().simple().to_string();
        let hex = raw.get(..HANDLE_LENGTH).unwrap_or(&raw);
        Self(format!("{SCHEME}{hex}"))
    }
}

/// One entry in the vault.
#[derive(Debug)]
struct SecretEntry {
    /// The name the credential is known by, such as `NOTION_API_KEY`.
    ///
    /// Safe to log; the value is not.
    key_name: String,
    /// The value, once the user has supplied one.
    value: Option<String>,
    /// When this was created or last used, for the idle sweep.
    last_touched: Instant,
    /// Wakes the request that is waiting on this handle.
    ///
    /// Taken on the first submission, so a second one is a refusal rather than
    /// a send on a closed channel.
    waiter: Option<oneshot::Sender<()>>,
}

/// The credentials a setup flow has collected, by handle.
///
/// One per host. Two would not see each other's handles, and a submission would
/// land in the wrong one.
#[derive(Debug, Default)]
pub struct SecretVault {
    entries: Mutex<HashMap<SecretRef, SecretEntry>>,
}

impl SecretVault {
    /// An empty vault.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    /// Mints a handle and parks a waiter against it.
    ///
    /// Returns the handle and the receiver to await. The caller shows the user
    /// a prompt for `key_name` and waits with [`Self::await_fulfillment`].
    pub async fn request(&self, key_name: &str) -> (SecretRef, oneshot::Receiver<()>) {
        let (sender, receiver) = oneshot::channel();
        let handle = SecretRef::mint();

        self.entries.lock().await.insert(
            handle.clone(),
            SecretEntry {
                key_name: key_name.to_string(),
                value: None,
                last_touched: Instant::now(),
                waiter: Some(sender),
            },
        );

        tracing::debug!(handle = handle.as_str(), key_name, "minted a secret handle");
        (handle, receiver)
    }

    /// Records the value a user supplied.
    ///
    /// Returns whether it was accepted. A handle that is unknown, or that
    /// already holds a value, is refused: a second submission against one
    /// handle is either a duplicate or a mistake, and quietly overwriting the
    /// first would replace a credential the user already confirmed.
    pub async fn submit(&self, handle: &SecretRef, value: String) -> bool {
        let mut entries = self.entries.lock().await;

        let Some(entry) = entries.get_mut(handle) else {
            tracing::warn!(
                handle = handle.as_str(),
                "a submission named an unknown handle"
            );
            return false;
        };

        if entry.value.is_some() {
            tracing::warn!(
                handle = handle.as_str(),
                "a handle was submitted against twice"
            );
            return false;
        }

        entry.value = Some(value);
        entry.last_touched = Instant::now();
        if let Some(waiter) = entry.waiter.take() {
            // The receiver may already be gone if the request timed out. That
            // is not an error: the value is stored, and a retry will find it.
            let _ = waiter.send(());
        }

        tracing::debug!(handle = handle.as_str(), "a secret handle was fulfilled");
        true
    }

    /// Waits for a handle to be fulfilled, giving up after [`REQUEST_TIMEOUT`].
    ///
    /// The handle is forgotten on either failure, so a timed-out request does
    /// not leave an entry nothing will ever answer.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MalformedResponse`] when the wait times out or the
    /// request is cancelled.
    pub async fn await_fulfillment(
        &self,
        handle: &SecretRef,
        receiver: oneshot::Receiver<()>,
    ) -> Result<()> {
        match tokio::time::timeout(REQUEST_TIMEOUT, receiver).await {
            Ok(Ok(())) => Ok(()),
            Ok(Err(_)) => {
                // The sender was dropped, which means the sweep took the entry.
                self.forget(handle).await;
                Err(Error::malformed(format!(
                    "the request for {} was cancelled before the user answered",
                    handle.as_str()
                )))
            }
            Err(_) => {
                self.forget(handle).await;
                Err(Error::malformed(format!(
                    "the request for {} went unanswered for {} seconds",
                    handle.as_str(),
                    REQUEST_TIMEOUT.as_secs()
                )))
            }
        }
    }

    /// Resolves handles to values, leaving them in the vault.
    ///
    /// All or nothing: an unknown or unfulfilled handle fails the whole call
    /// rather than returning a partial set. A connection test run with half a
    /// server's credentials fails in a way that tells the user nothing useful.
    ///
    /// Touches every handle it resolved, so repeated connection tests keep the
    /// idle sweep at bay.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MalformedResponse`] naming the first handle that is
    /// unknown or not yet answered.
    pub async fn resolve(
        &self,
        handles: &HashMap<String, SecretRef>,
    ) -> Result<Vec<(String, String)>> {
        let mut entries = self.entries.lock().await;
        Self::resolve_locked(&mut entries, handles)
    }

    /// Resolves handles and removes them.
    ///
    /// For the step that has committed the values somewhere durable. Both
    /// halves happen under one lock, so nothing can submit against or sweep a
    /// handle between resolving it and dropping it.
    ///
    /// # Errors
    ///
    /// As [`Self::resolve`]. Nothing is removed when it fails, so a caller can
    /// fix the problem and retry without asking the user again.
    pub async fn consume(
        &self,
        handles: &HashMap<String, SecretRef>,
    ) -> Result<Vec<(String, String)>> {
        let mut entries = self.entries.lock().await;
        let resolved = Self::resolve_locked(&mut entries, handles)?;

        for handle in handles.values() {
            entries.remove(handle);
        }

        Ok(resolved)
    }

    /// The resolution both paths share, with the lock already held.
    fn resolve_locked(
        entries: &mut HashMap<SecretRef, SecretEntry>,
        handles: &HashMap<String, SecretRef>,
    ) -> Result<Vec<(String, String)>> {
        let mut resolved = Vec::with_capacity(handles.len());

        for (key_name, handle) in handles {
            let entry = entries.get_mut(handle).ok_or_else(|| {
                Error::malformed(format!("no such secret handle: {}", handle.as_str()))
            })?;

            let value = entry.value.clone().ok_or_else(|| {
                Error::malformed(format!(
                    "the secret handle {} has not been answered yet",
                    handle.as_str()
                ))
            })?;

            entry.last_touched = Instant::now();
            resolved.push((key_name.clone(), value));
        }

        Ok(resolved)
    }

    /// Drops one handle, reporting whether there was one.
    ///
    /// For a setup the user walked away from half-finished.
    pub async fn forget(&self, handle: &SecretRef) -> bool {
        self.entries.lock().await.remove(handle).is_some()
    }

    /// Drops every handle idle longer than [`IDLE_TTL`], reporting how many.
    ///
    /// Cheap enough to call often.
    pub async fn sweep(&self) -> usize {
        let now = Instant::now();
        let mut entries = self.entries.lock().await;

        let before = entries.len();
        entries.retain(|_, entry| now.duration_since(entry.last_touched) < IDLE_TTL);
        let reaped = before - entries.len();

        if reaped > 0 {
            tracing::debug!(reaped, "swept idle secret handles");
        }
        reaped
    }

    /// How many handles the vault holds.
    pub async fn len(&self) -> usize {
        self.entries.lock().await.len()
    }

    /// Whether the vault holds nothing.
    pub async fn is_empty(&self) -> bool {
        self.len().await == 0
    }

    /// The name a handle was requested under.
    ///
    /// The *name*, never the value. A caller re-prompting after a timeout needs
    /// to know what to ask for again.
    pub async fn key_name(&self, handle: &SecretRef) -> Option<String> {
        self.entries
            .lock()
            .await
            .get(handle)
            .map(|entry| entry.key_name.clone())
    }
}

//! Browser OAuth for HTTP-remote servers, per the MCP authorization spec.
//!
//! Many remote MCP servers gate access behind OAuth 2.0 with authorization code
//! and PKCE, advertised through a 401 challenge pointing at a
//! protected-resource document. This module runs that flow.
//!
//! # The three steps
//!
//! 1. [`OAuthFlow::detect`] classifies a server: open, static token, or browser
//!    sign-in. It does so by *probing*, not by reading registry metadata, which
//!    is frequently wrong about this.
//! 2. [`OAuthFlow::begin`] discovers the authorization server, registers a
//!    client dynamically (RFC 7591), generates a PKCE pair, parks the pending
//!    state, and returns the authorize URL for a browser.
//! 3. [`OAuthFlow::complete`] takes the code and state from the redirect,
//!    exchanges the code, and persists the token.
//!
//! # The redirect URI is the host's to supply
//!
//! A loopback redirect (RFC 8252) needs a listener, and the host owns it: it
//! knows which port it actually bound, which may not be the one it asked for.
//! [`OAuthFlow::begin`] therefore *takes* the redirect URI rather than deriving
//! it. Deriving it here would mean this module reading the host's environment
//! variables and guessing — and a guess that is wrong sends the browser to a
//! dead port, where sign-in simply hangs.
//!
//! # Completing does not reconnect
//!
//! [`OAuthFlow::complete`] persists the token and stops. Reconnecting is the
//! caller's job. That keeps this module free of any dependency on the live
//! connection map, which in turn is what lets the connection map depend on
//! *this* one for [`refresh_if_expired`] without a cycle.
//!
//! # What is stored, and where
//!
//! The access token is stored as the server's `Authorization` header value, so
//! the ordinary connect path picks it up with no special case. The bookkeeping
//! needed to mint a new one — refresh token, client credentials, token endpoint,
//! expiry — is stored beside it under [`OAUTH_BUNDLE_KEY`]. That key begins with
//! two underscores, which is the marker meaning "never send this as a request
//! header and never show it in a credential list".

pub(crate) mod flow;
pub(crate) mod tokens;
pub(crate) mod types;

pub use flow::OAuthFlow;
pub use tokens::{OAUTH_BUNDLE_KEY, refresh_if_expired};
pub use types::{AuthDetection, AuthKind};

#[cfg(test)]
mod test;

//! Storing and refreshing OAuth tokens.

use std::time::{SystemTime, UNIX_EPOCH};

use serde_json::Value;

use super::types::{OAuthBundle, TokenResponse};
use crate::error::{Error, Result};
use crate::registry::Store;

/// The reserved credential key holding the refresh bundle.
///
/// The two leading underscores are the marker meaning "internal": the connect
/// path skips such keys when building request headers, so this is never sent to
/// a server, and a credential listing hides them from the user.
pub const OAUTH_BUNDLE_KEY: &str = "__oauth__";

/// The credential key the access token is stored under.
///
/// It is the header name on purpose. Storing the token as an ordinary
/// `Authorization` value means the connect path needs no special case for an
/// OAuth server — it builds headers from stored credentials either way.
pub(super) const ACCESS_TOKEN_KEY: &str = "Authorization";

/// How long before expiry a token is treated as already expired.
///
/// A token that expires during the request it was attached to is a 401 the user
/// sees for no reason.
const REFRESH_SKEW_SECS: u64 = 60;

/// The lifetime assumed when a server does not state one.
const DEFAULT_TOKEN_LIFETIME_SECS: u64 = 3600;

/// Mints a new access token when the stored one has expired, or is about to.
///
/// Returns whether a refresh happened. Does nothing — and reports `false` — for
/// a server with no bundle, a bundle with no refresh token, or a token that is
/// still good. A server with no refresh token simply gets a 401 on its next
/// call, which prompts the user to sign in again.
///
/// Called from the connect path so a session never opens with a stale token.
///
/// # Errors
///
/// Returns [`Error::MalformedResponse`] when the stored bundle cannot be read
/// or the token endpoint answers with something unusable, [`Error::Http`] when
/// it answers with a failure status, and [`Error::Transport`] when it cannot be
/// reached.
pub async fn refresh_if_expired(
    store: &Store,
    http: &reqwest::Client,
    server_id: &str,
) -> Result<bool> {
    let env = store.load_env_values(server_id)?;
    let Some(raw_bundle) = env.get(OAUTH_BUNDLE_KEY) else {
        return Ok(false);
    };

    let bundle: OAuthBundle = serde_json::from_str(raw_bundle)
        .map_err(|error| Error::malformed(format!("stored oauth bundle is unreadable: {error}")))?;

    if bundle.expires_at > now_unix() + REFRESH_SKEW_SECS {
        return Ok(false);
    }

    let Some(refresh_token) = bundle
        .refresh_token
        .as_deref()
        .filter(|token| !token.trim().is_empty())
    else {
        return Ok(false);
    };

    let mut form: Vec<(&str, &str)> = vec![
        ("grant_type", "refresh_token"),
        ("refresh_token", refresh_token),
        ("client_id", bundle.client_id.as_str()),
    ];
    if let Some(secret) = bundle.client_secret.as_deref() {
        form.push(("client_secret", secret));
    }

    let body = post_form(http, &bundle.token_endpoint, &form).await?;
    let mut tokens = TokenResponse::parse(&body)?;

    // Some servers do not rotate the refresh token. Keeping the existing one is
    // what stops a refresh from being the last one possible.
    if tokens.refresh_token.is_none() {
        tokens.refresh_token.clone_from(&bundle.refresh_token);
    }

    persist(
        store,
        server_id,
        &bundle.client_id,
        bundle.client_secret.as_deref(),
        &bundle.token_endpoint,
        &tokens,
    )?;

    tracing::info!(server_id, "refreshed an expired access token");
    Ok(true)
}

/// Stores an access token and its refresh bundle.
///
/// Merged over the existing credentials rather than replacing them. Storing is
/// replace-all, so starting from an empty map would silently erase any custom
/// header the user configured alongside their sign-in.
///
/// # Errors
///
/// Returns [`Error::Serialization`] when the bundle cannot be encoded, and
/// [`Error::Store`] when it cannot be written.
pub(super) fn persist(
    store: &Store,
    server_id: &str,
    client_id: &str,
    client_secret: Option<&str>,
    token_endpoint: &str,
    tokens: &TokenResponse,
) -> Result<()> {
    let bundle = OAuthBundle {
        refresh_token: tokens.refresh_token.clone(),
        client_id: client_id.to_string(),
        client_secret: client_secret.map(ToString::to_string),
        token_endpoint: token_endpoint.to_string(),
        expires_at: now_unix() + tokens.expires_in.unwrap_or(DEFAULT_TOKEN_LIFETIME_SECS),
    };

    let mut env = store.load_env_values(server_id)?;
    env.insert(
        ACCESS_TOKEN_KEY.to_string(),
        format!("Bearer {}", tokens.access_token),
    );
    env.insert(
        OAUTH_BUNDLE_KEY.to_string(),
        serde_json::to_string(&bundle)?,
    );

    store.set_env_values(server_id, &env)?;

    // The listing of credential *names* lives on the server row and is what a
    // caller shows the user, so it has to learn about the two new keys.
    let names: Vec<String> = env.keys().cloned().collect();
    store.update_env_keys(server_id, &names)?;

    Ok(())
}

/// Posts a form to a token endpoint and returns its JSON body.
///
/// # Errors
///
/// Returns [`Error::Transport`] when the endpoint cannot be reached,
/// [`Error::Http`] when it answers with a failure status, and
/// [`Error::MalformedResponse`] when the body is not JSON.
pub(super) async fn post_form(
    http: &reqwest::Client,
    endpoint: &str,
    form: &[(&str, &str)],
) -> Result<Value> {
    let response = http
        .post(endpoint)
        .form(form)
        .send()
        .await
        .map_err(|error| Error::transport(endpoint, error))?;

    let status = response.status();
    let text = response
        .text()
        .await
        .map_err(|error| Error::transport(endpoint, error))?;

    // The body is read before the status is judged, because a token endpoint's
    // failure body is where it says *why* — `invalid_grant`, `invalid_client`.
    // Discarding it would leave a caller with a bare status code.
    if !status.is_success() {
        return Err(Error::Http {
            endpoint: crate::redact_endpoint(endpoint),
            status: status.as_u16(),
            body: text,
        });
    }

    serde_json::from_str(&text)
        .map_err(|error| Error::malformed(format!("token endpoint replied with non-json: {error}")))
}

/// The current time in Unix seconds.
///
/// A clock before the epoch reads as zero, which makes every token look expired
/// and triggers a refresh. That is the safe direction to be wrong in.
pub(super) fn now_unix() -> u64 {
    SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |elapsed| elapsed.as_secs())
}

//! The values the authorization flow passes around.

use serde::{Deserialize, Serialize};
use serde_json::Value;

use crate::error::{Error, Result};

/// What a server wants before it will talk.
///
/// Drives which control a caller offers the user, and getting it wrong costs
/// them a sign-in that cannot work or a token field for a server that will
/// never accept one.
#[derive(Debug, Clone, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub struct AuthDetection {
    /// `none`, `token`, or `oauth`.
    pub kind: AuthKind,
    /// Where to send the user, for an OAuth challenge.
    #[serde(default)]
    pub authorization_endpoint: Option<String>,
    /// The grant types the authorization server listed, if it listed any.
    #[serde(default)]
    pub grant_types: Vec<String>,
}

impl AuthDetection {
    /// A server that wants nothing.
    #[must_use]
    pub fn open() -> Self {
        Self {
            kind: AuthKind::None,
            authorization_endpoint: None,
            grant_types: Vec::new(),
        }
    }

    /// A server that wants a static credential.
    #[must_use]
    pub fn static_token() -> Self {
        Self {
            kind: AuthKind::Token,
            authorization_endpoint: None,
            grant_types: Vec::new(),
        }
    }

    /// A server that wants a browser sign-in.
    #[must_use]
    pub fn oauth(authorization_endpoint: String, grant_types: Vec<String>) -> Self {
        Self {
            kind: AuthKind::Oauth,
            authorization_endpoint: Some(authorization_endpoint),
            grant_types,
        }
    }
}

/// The three kinds of thing a server can want.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
#[non_exhaustive]
pub enum AuthKind {
    /// The server answered without a challenge. Nothing to supply.
    None,
    /// A static bearer token or API key, which the user pastes.
    Token,
    /// A browser sign-in.
    Oauth,
}

impl AuthKind {
    /// The stable string this kind is transmitted as.
    #[must_use]
    pub const fn as_str(self) -> &'static str {
        match self {
            Self::None => "none",
            Self::Token => "token",
            Self::Oauth => "oauth",
        }
    }
}

/// An authorization parked between the browser redirect out and back.
#[derive(Debug, Clone)]
pub(super) struct PendingAuthorization {
    /// Which install this authorization is for.
    pub(super) server_id: String,
    /// The PKCE verifier, sent with the code exchange.
    pub(super) code_verifier: String,
    /// The dynamically registered client.
    pub(super) client_id: String,
    /// The secret, when the server issued a confidential client.
    pub(super) client_secret: Option<String>,
    /// Where to exchange the code.
    pub(super) token_endpoint: String,
    /// The redirect the authorization was started with.
    pub(super) redirect_uri: String,
    /// When this was parked, in Unix seconds.
    ///
    /// Present so an authorization the user abandoned does not sit in memory
    /// holding a client secret forever.
    pub(super) started_at: u64,
}

/// The bookkeeping needed to mint a new access token without another sign-in.
///
/// Stored beside the access token under the reserved bundle key. The access
/// token itself is the `Authorization` header value, so the ordinary connect
/// path needs no special case for an OAuth server.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub(super) struct OAuthBundle {
    /// The refresh token, when the server issued one.
    pub(super) refresh_token: Option<String>,
    /// The registered client.
    pub(super) client_id: String,
    /// The client secret, when there is one.
    pub(super) client_secret: Option<String>,
    /// Where to refresh.
    pub(super) token_endpoint: String,
    /// When the current access token expires, in Unix seconds. Best effort.
    pub(super) expires_at: u64,
}

/// A parsed token-endpoint reply.
#[derive(Debug, Clone)]
pub(super) struct TokenResponse {
    /// The access token.
    pub(super) access_token: String,
    /// A rotated refresh token, when the server sent one.
    pub(super) refresh_token: Option<String>,
    /// How long the access token lasts, in seconds.
    pub(super) expires_in: Option<u64>,
}

impl TokenResponse {
    /// Reads a token-endpoint reply.
    ///
    /// Only the access token is required. A server that omits the refresh token
    /// or the lifetime is normal, and refusing its reply would break sign-in
    /// for it.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MalformedResponse`] when there is no access token,
    /// which is the one thing the flow cannot proceed without.
    pub(super) fn parse(body: &Value) -> Result<Self> {
        let access_token = body
            .get("access_token")
            .and_then(Value::as_str)
            .ok_or_else(|| Error::malformed("token response has no access_token"))?
            .to_string();

        Ok(Self {
            access_token,
            refresh_token: body
                .get("refresh_token")
                .and_then(Value::as_str)
                .map(ToString::to_string),
            expires_in: body.get("expires_in").and_then(Value::as_u64),
        })
    }
}

//! Running the authorization-code flow.

use std::collections::HashMap;
use std::time::Duration;

use base64::Engine as _;
use parking_lot::Mutex;
use reqwest::Url;
use serde_json::{Value, json};
use sha2::{Digest, Sha256};

use super::tokens::{persist, post_form};
use super::types::{AuthDetection, PendingAuthorization, TokenResponse};
use crate::error::{Error, Result};
use crate::registry::Store;
use crate::transport::http::McpHttpClient;
use tinymcp_bus::{McpProxyConfig, Transport};

/// URL-safe base64 without padding, which is what OAuth uses throughout.
const B64: base64::engine::general_purpose::GeneralPurpose =
    base64::engine::general_purpose::URL_SAFE_NO_PAD;

/// How long an unfinished authorization stays parked.
///
/// A user who starts a sign-in and closes the tab leaves an entry behind
/// holding a client secret. Ten minutes is longer than any real sign-in and
/// short enough that abandoned ones do not accumulate.
const PENDING_TTL: Duration = Duration::from_secs(10 * 60);

/// How long to wait on an authorization server.
const AUTH_SERVER_TIMEOUT_SECS: u64 = 20;

/// How long to wait when probing a server for what it wants.
const PROBE_TIMEOUT_SECS: u64 = 20;

/// The client name presented during dynamic registration.
///
/// A user sees this on the consent screen, so it names the library rather than
/// leaving it blank. A host that wants its own name there registers its own
/// client; that is a larger change than a string.
const CLIENT_NAME: &str = "TinyMCP";

/// Runs browser sign-in for HTTP-remote servers.
///
/// Holds the authorizations parked between the redirect out and back. One
/// instance per host; two would not see each other's pending state, and a
/// redirect would come back to the wrong one.
#[derive(Debug)]
pub struct OAuthFlow {
    http: reqwest::Client,
    proxy: Option<McpProxyConfig>,
    pending: Mutex<HashMap<String, PendingAuthorization>>,
}

impl OAuthFlow {
    /// Builds a flow that dials through `proxy`.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ClientBuild`] when the HTTP client cannot be built.
    pub fn new(proxy: Option<McpProxyConfig>) -> Result<Self> {
        let http = reqwest::Client::builder()
            .timeout(Duration::from_secs(AUTH_SERVER_TIMEOUT_SECS))
            .build()
            .map_err(|source| Error::ClientBuild {
                source: Box::new(source.without_url()),
            })?;

        Ok(Self {
            http,
            proxy,
            pending: Mutex::new(HashMap::new()),
        })
    }

    /// The HTTP client this flow uses, for the refresh path.
    #[must_use]
    pub fn http(&self) -> &reqwest::Client {
        &self.http
    }

    /// Classifies what a server wants before it will talk.
    ///
    /// Decided by probing, not by reading registry metadata, which is often
    /// wrong about this. A server that answers without a challenge is open; one
    /// that challenges with a usable authorization endpoint wants a browser
    /// sign-in; anything else wants a static token.
    ///
    /// A discovery failure reports a static token rather than an error. The
    /// user can paste one and find out, which beats being blocked by a probe
    /// that could not parse an unusual challenge.
    ///
    /// # Errors
    ///
    /// Returns [`Error::UnknownServer`] when there is no such install, and
    /// [`Error::Store`] when it cannot be read. A store failure is *not*
    /// collapsed into "open": reporting a server as needing nothing when the
    /// lookup failed would show the user a state that was never checked.
    pub async fn detect(&self, store: &Store, server_id: &str) -> Result<AuthDetection> {
        let Some(url) = Self::remote_url(store, server_id)? else {
            // A subprocess install has no HTTP authorization to discover.
            return Ok(AuthDetection::open());
        };

        let client = McpHttpClient::builder(url)
            .timeout_secs(PROBE_TIMEOUT_SECS)
            .proxy(self.proxy.clone())
            .build()?;

        match client.discover_authorization().await {
            Ok(None) => Ok(AuthDetection::open()),
            Ok(Some(context)) => Ok(context
                .authorization_server_metadata
                .iter()
                .find(|metadata| {
                    metadata.authorization_endpoint.is_some()
                        && supports_authorization_code(metadata)
                })
                .and_then(|metadata| {
                    metadata.authorization_endpoint.clone().map(|endpoint| {
                        AuthDetection::oauth(endpoint, metadata.grant_types_supported.clone())
                    })
                })
                .unwrap_or_else(AuthDetection::static_token)),
            Err(error) => {
                tracing::debug!(
                    server_id,
                    "discovery failed; offering a static token instead: {error}"
                );
                Ok(AuthDetection::static_token())
            }
        }
    }

    /// Starts a sign-in and returns the URL to open in a browser.
    ///
    /// `redirect_uri` is the loopback address the host is listening on. It is a
    /// parameter because only the host knows which port it actually bound — see
    /// the module note.
    ///
    /// # Errors
    ///
    /// Returns [`Error::AuthDiscovery`] when no advertised authorization server
    /// offers everything the flow needs, [`Error::MalformedResponse`] when
    /// registration answers with something unusable, plus whatever the
    /// transport returns.
    pub async fn begin(
        &self,
        store: &Store,
        server_id: &str,
        redirect_uri: &str,
    ) -> Result<String> {
        let url = Self::remote_url(store, server_id)?
            .ok_or_else(|| Error::malformed("oauth applies only to http-remote servers"))?;

        let client = McpHttpClient::builder(url.clone())
            .timeout_secs(PROBE_TIMEOUT_SECS)
            .proxy(self.proxy.clone())
            .build()?;

        let context = client
            .discover_authorization()
            .await?
            .ok_or_else(|| Error::malformed("the server does not require authorization"))?;

        // Chosen by capability rather than by position: the first advertised
        // authorization server may be incomplete while a later one is usable.
        let metadata = context
            .authorization_server_metadata
            .iter()
            .find(|metadata| {
                metadata.authorization_endpoint.is_some()
                    && metadata.token_endpoint.is_some()
                    && metadata.registration_endpoint.is_some()
                    && supports_authorization_code(metadata)
            })
            .ok_or_else(|| Error::AuthDiscovery {
                detail: "no advertised authorization server offers an authorize endpoint, a token \
                         endpoint, and dynamic client registration together"
                    .to_string(),
                challenge: Box::new(context.challenge.clone()),
            })?;

        // Each was checked present by the search above.
        let (Some(authorization_endpoint), Some(token_endpoint), Some(registration_endpoint)) = (
            metadata.authorization_endpoint.clone(),
            metadata.token_endpoint.clone(),
            metadata.registration_endpoint.clone(),
        ) else {
            return Err(Error::malformed(
                "the chosen authorization server lost an endpoint between checks",
            ));
        };

        let (client_id, client_secret) = self
            .register_client(&registration_endpoint, redirect_uri)
            .await?;

        let (code_verifier, code_challenge) = generate_pkce();
        let state = uuid::Uuid::new_v4().to_string();

        {
            let mut pending = self.pending.lock();
            prune_expired(&mut pending);
            pending.insert(
                state.clone(),
                PendingAuthorization {
                    server_id: server_id.to_string(),
                    code_verifier,
                    client_id: client_id.clone(),
                    client_secret,
                    token_endpoint,
                    redirect_uri: redirect_uri.to_string(),
                    started_at: super::tokens::now_unix(),
                },
            );
        }

        let authorize_url = Url::parse_with_params(
            &authorization_endpoint,
            &[
                ("response_type", "code"),
                ("client_id", client_id.as_str()),
                ("redirect_uri", redirect_uri),
                ("code_challenge", code_challenge.as_str()),
                ("code_challenge_method", "S256"),
                ("state", state.as_str()),
                ("resource", url.as_str()),
            ],
        )
        .map_err(|error| Error::malformed(format!("could not build an authorize url: {error}")))?;

        tracing::info!(server_id, client_id, "started an oauth authorization");
        Ok(authorize_url.to_string())
    }

    /// Finishes a sign-in from the redirect's `code` and `state`.
    ///
    /// Exchanges the code and stores the token. Returns the install the
    /// authorization was for, so the caller can reconnect it — see the module
    /// note on why reconnecting is not done here.
    ///
    /// The pending entry is consumed whether or not the exchange succeeds: a
    /// code is single-use, so a retry with the same state could never work and
    /// keeping the entry would only hold a secret in memory.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MalformedResponse`] when the state is unknown or
    /// expired, plus whatever the token endpoint returns.
    pub async fn complete(&self, store: &Store, state: &str, code: &str) -> Result<String> {
        let pending = {
            let mut pending = self.pending.lock();
            prune_expired(&mut pending);
            pending.remove(state)
        }
        .ok_or_else(|| Error::malformed("unknown or expired oauth state"))?;

        let mut form: Vec<(&str, &str)> = vec![
            ("grant_type", "authorization_code"),
            ("code", code),
            ("redirect_uri", pending.redirect_uri.as_str()),
            ("client_id", pending.client_id.as_str()),
            ("code_verifier", pending.code_verifier.as_str()),
        ];
        if let Some(secret) = pending.client_secret.as_deref() {
            form.push(("client_secret", secret));
        }

        let body = post_form(&self.http, &pending.token_endpoint, &form).await?;
        let tokens = TokenResponse::parse(&body)?;

        persist(
            store,
            &pending.server_id,
            &pending.client_id,
            pending.client_secret.as_deref(),
            &pending.token_endpoint,
            &tokens,
        )?;

        tracing::info!(
            server_id = %pending.server_id,
            "completed an oauth authorization and stored the token"
        );
        Ok(pending.server_id)
    }

    /// How many authorizations are parked. For tests and diagnostics.
    #[must_use]
    pub fn pending_count(&self) -> usize {
        let mut pending = self.pending.lock();
        prune_expired(&mut pending);
        pending.len()
    }

    /// Registers a client dynamically, per RFC 7591.
    ///
    /// A confidential client is requested, and the secret is kept when one is
    /// issued: some servers issue one regardless of what was asked for, and the
    /// token exchange then fails without it.
    async fn register_client(
        &self,
        registration_endpoint: &str,
        redirect_uri: &str,
    ) -> Result<(String, Option<String>)> {
        let body = json!({
            "client_name": CLIENT_NAME,
            "redirect_uris": [redirect_uri],
            "grant_types": ["authorization_code", "refresh_token"],
            "response_types": ["code"],
            "token_endpoint_auth_method": "client_secret_post",
        });

        let response = self
            .http
            .post(registration_endpoint)
            .json(&body)
            .send()
            .await
            .map_err(|error| Error::transport(registration_endpoint, error))?;

        let status = response.status();
        let text = response
            .text()
            .await
            .map_err(|error| Error::transport(registration_endpoint, error))?;

        if !status.is_success() {
            return Err(Error::Http {
                endpoint: crate::redact_endpoint(registration_endpoint),
                status: status.as_u16(),
                body: text,
            });
        }

        let registered: Value = serde_json::from_str(&text).map_err(|error| {
            Error::malformed(format!(
                "client registration replied with non-json: {error}"
            ))
        })?;

        let client_id = registered
            .get("client_id")
            .and_then(Value::as_str)
            .ok_or_else(|| Error::malformed("client registration returned no client_id"))?
            .to_string();

        let client_secret = registered
            .get("client_secret")
            .and_then(Value::as_str)
            .map(ToString::to_string);

        Ok((client_id, client_secret))
    }

    /// The endpoint of an HTTP-remote install, or `None` for a subprocess one.
    fn remote_url(store: &Store, server_id: &str) -> Result<Option<String>> {
        let server = store.get_server(server_id)?;
        Ok(match server.transport {
            Transport::HttpRemote { ref url } if !url.is_empty() => Some(url.clone()),
            _ => None,
        })
    }
}

/// Whether an authorization server will accept an authorization code.
///
/// An empty list counts as yes. RFC 8414 makes the field optional and says it
/// *defaults* to including `authorization_code`, and servers do omit it — so
/// requiring it would reject servers that work.
fn supports_authorization_code(metadata: &tinymcp_bus::AuthorizationServerMetadata) -> bool {
    metadata.grant_types_supported.is_empty()
        || metadata
            .grant_types_supported
            .iter()
            .any(|grant| grant == "authorization_code")
}

/// Generates a PKCE verifier and its S256 challenge.
///
/// The verifier is 48 bytes of entropy from three version-4 identifiers,
/// base64url-encoded to 64 characters — inside the 43-to-128 range the
/// specification requires.
fn generate_pkce() -> (String, String) {
    let mut bytes = Vec::with_capacity(48);
    for _ in 0..3 {
        bytes.extend_from_slice(uuid::Uuid::new_v4().as_bytes());
    }

    let verifier = B64.encode(bytes);
    let challenge = B64.encode(Sha256::digest(verifier.as_bytes()));
    (verifier, challenge)
}

/// Drops authorizations the user never finished.
///
/// Each holds a client secret, so leaving them is a slow leak of credentials
/// into a map nothing ever reads again.
fn prune_expired(pending: &mut HashMap<String, PendingAuthorization>) {
    let cutoff = super::tokens::now_unix().saturating_sub(PENDING_TTL.as_secs());
    pending.retain(|_, authorization| authorization.started_at >= cutoff);
}

/// Exposes [`generate_pkce`] to the module's tests.
#[cfg(test)]
pub(super) fn generate_pkce_for_test() -> (String, String) {
    generate_pkce()
}

//! The official registry's wire shapes, and how they become catalog rows.
//!
//! These are deliberately permissive — every nested field is optional — so a
//! schema bump upstream does not stop the catalog parsing. There is one
//! exception, marked below, where permissiveness caused the bug it was supposed
//! to prevent.

use serde::Deserialize;
use serde_json::{Map, Value};

use super::super::types::SOURCE_MCP_OFFICIAL;
use tinymcp_bus::{ExtraFields, RegistryConnection, RegistryServerDetail, RegistryServerSummary};

/// The value `auth_kind` takes for a server declaring a static credential.
const AUTH_KIND_API_KEY: &str = "api_key";

/// The status the registry marks a withdrawn version with.
const STATUS_DEPRECATED: &str = "deprecated";

/// Where the registry keeps its own bookkeeping inside a row's metadata.
const REGISTRY_META_KEY: &str = "io.modelcontextprotocol.registry/official";

/// A page of the list endpoint.
#[derive(Debug, Clone, Deserialize)]
pub(super) struct OfficialListResponse {
    #[serde(default)]
    servers: Vec<OfficialServerEnvelope>,
    #[serde(default)]
    metadata: Option<OfficialMetadata>,
}

impl OfficialListResponse {
    /// The rows worth showing, deduplicated by name.
    ///
    /// Drops anything that cannot actually be installed and anything the
    /// registry has deprecated. Both are noise: a row a user cannot install is
    /// a dead end they can only discover by trying.
    pub(super) fn into_summaries(self) -> Vec<RegistryServerSummary> {
        let mut seen = std::collections::HashSet::new();

        self.servers
            .into_iter()
            .filter(|envelope| envelope.is_installable() && !envelope.is_deprecated())
            .filter_map(|envelope| {
                seen.insert(envelope.server.name.clone())
                    .then(|| envelope.server.into_summary())
            })
            .collect()
    }

    /// The cursor for the next page, when there is one.
    ///
    /// An empty string counts as absent — the registry sends one at the end of
    /// a result set, and treating it as a cursor would page forever.
    pub(super) fn next_cursor(&self) -> Option<&str> {
        self.metadata
            .as_ref()
            .and_then(|metadata| metadata.next_cursor.as_deref())
            .filter(|cursor| !cursor.is_empty())
    }
}

/// The page metadata.
#[derive(Debug, Clone, Deserialize)]
struct OfficialMetadata {
    #[serde(default, rename = "nextCursor")]
    next_cursor: Option<String>,
}

/// One row of the list endpoint.
///
/// # Why `server` has no default
///
/// Everything else here is optional so an upstream schema change does not stop
/// the catalog working. This field is the exception, and deliberately: an
/// earlier version of this adapter parsed the *inner* shape at the top level,
/// so serde filled every field with a default and the catalog silently rendered
/// pages of blank cards. A missing `server` key has to be a parse error, or the
/// same failure comes back looking like an empty registry.
#[derive(Debug, Clone, Deserialize)]
struct OfficialServerEnvelope {
    server: OfficialServer,
    #[serde(default, rename = "_meta")]
    meta: Option<Value>,
}

impl OfficialServerEnvelope {
    /// Whether this row offers any way to connect at all.
    fn is_installable(&self) -> bool {
        !self.server.remotes.is_empty() || !self.server.packages.is_empty()
    }

    /// Whether the registry has withdrawn this version.
    ///
    /// Absent metadata counts as not deprecated, which is what a row cached by
    /// an older build looks like.
    fn is_deprecated(&self) -> bool {
        self.meta
            .as_ref()
            .and_then(|meta| meta.get(REGISTRY_META_KEY))
            .and_then(|registry| registry.get("status"))
            .and_then(Value::as_str)
            == Some(STATUS_DEPRECATED)
    }
}

/// One server, as the official registry describes it.
#[derive(Debug, Clone, Default, Deserialize)]
pub(super) struct OfficialServer {
    /// The reverse-DNS identifier, such as `io.github.foo/server-bar`.
    #[serde(default)]
    pub(super) name: String,
    #[serde(default)]
    title: Option<String>,
    #[serde(default)]
    description: Option<String>,
    #[serde(default, rename = "iconUrl")]
    icon_url: Option<String>,
    /// Hosted endpoints.
    #[serde(default)]
    pub(super) remotes: Vec<OfficialRemote>,
    /// Installable subprocess packages.
    #[serde(default)]
    pub(super) packages: Vec<OfficialPackage>,
    #[serde(default, rename = "websiteUrl")]
    website_url: Option<String>,
}

impl OfficialServer {
    /// The declared vendor site, when it declares a non-blank one.
    fn website(&self) -> Option<String> {
        self.website_url
            .as_deref()
            .map(str::trim)
            .filter(|url| !url.is_empty())
            .map(ToString::to_string)
    }

    /// Whether the server declares a named static credential.
    ///
    /// A secret header, an `Authorization` header, or a secret environment
    /// variable. This is metadata, not a probe: it is what lets the catalog say
    /// "this needs an API key" without dialling anything.
    fn declares_secret_credential(&self) -> bool {
        let secret_header = self.remotes.iter().any(|remote| {
            remote.headers.iter().any(|header| {
                header.is_secret == Some(true) || header.name.eq_ignore_ascii_case("authorization")
            })
        });

        let secret_variable = self.packages.iter().any(|package| {
            package
                .environment_variables
                .iter()
                .any(|variable| variable.is_secret == Some(true))
        });

        secret_header || secret_variable
    }

    /// A readable name.
    ///
    /// The declared title when there is one. Otherwise the last segment of the
    /// reverse-DNS name with separators turned into spaces, which is a better
    /// thing to show a user than `io.github.someone/some-server`.
    pub(super) fn display_name(&self) -> String {
        if let Some(title) = self
            .title
            .as_deref()
            .filter(|title| !title.trim().is_empty())
        {
            return title.to_string();
        }

        let segment = self
            .name
            .rsplit_once('/')
            .map(|(_, last)| last)
            .or_else(|| self.name.rsplit_once('.').map(|(_, last)| last))
            .unwrap_or(&self.name);

        segment.replace(['-', '_'], " ")
    }

    /// This server as a catalog row.
    pub(super) fn into_summary(self) -> RegistryServerSummary {
        let display_name = self.display_name();
        let website_url = self.website();
        let auth_kind = self
            .declares_secret_credential()
            .then(|| AUTH_KIND_API_KEY.to_string());

        RegistryServerSummary {
            qualified_name: self.name,
            display_name,
            description: self.description,
            icon_url: self.icon_url,
            // The official registry publishes no install count.
            use_count: 0,
            is_deployed: !self.remotes.is_empty(),
            source: SOURCE_MCP_OFFICIAL.to_string(),
            // Badged later, by curation, from its own list.
            official: false,
            website_url,
            auth_kind,
            extra: ExtraFields::new(),
        }
    }

    /// This server as a detail record, with one connection per way in.
    pub(super) fn into_detail(self) -> RegistryServerDetail {
        let display_name = self.display_name();

        let mut connections = Vec::with_capacity(self.remotes.len() + self.packages.len());

        for remote in &self.remotes {
            connections.push(RegistryConnection {
                r#type: "http".to_string(),
                deployment_url: remote.url.clone(),
                config_schema: remote.to_config_schema(),
                example_config: None,
                published: true,
                extra: ExtraFields::new(),
            });
        }

        for package in &self.packages {
            connections.push(RegistryConnection {
                r#type: "stdio".to_string(),
                deployment_url: None,
                config_schema: package.to_config_schema(),
                example_config: Some(package.to_example_config()),
                published: true,
                extra: ExtraFields::new(),
            });
        }

        RegistryServerDetail {
            qualified_name: self.name,
            display_name,
            description: self.description,
            icon_url: self.icon_url,
            connections,
            source: SOURCE_MCP_OFFICIAL.to_string(),
            extra: ExtraFields::new(),
        }
    }
}

/// A hosted endpoint.
#[derive(Debug, Clone, Deserialize)]
pub(super) struct OfficialRemote {
    #[serde(default)]
    url: Option<String>,
    /// The inputs it wants, sent as request headers.
    #[serde(default)]
    headers: Vec<OfficialHeader>,
}

impl OfficialRemote {
    /// The declared headers as an input schema, so an install form can prompt
    /// for each one. `None` when the remote declares none.
    fn to_config_schema(&self) -> Option<Value> {
        build_schema(self.headers.iter().map(|header| SchemaField {
            name: &header.name,
            description: header.description.as_deref(),
            is_secret: header.is_secret == Some(true),
            is_required: header.is_required == Some(true),
        }))
    }
}

/// One declared header.
#[derive(Debug, Clone, Deserialize)]
struct OfficialHeader {
    #[serde(default)]
    name: String,
    #[serde(default)]
    description: Option<String>,
    #[serde(default, rename = "isRequired")]
    is_required: Option<bool>,
    #[serde(default, rename = "isSecret")]
    is_secret: Option<bool>,
}

/// An installable package.
#[derive(Debug, Clone, Deserialize)]
pub(super) struct OfficialPackage {
    #[serde(default, rename = "registryType")]
    registry_type: Option<String>,
    #[serde(default)]
    identifier: Option<String>,
    #[serde(default, rename = "runtimeHint")]
    runtime_hint: Option<String>,
    #[serde(default, rename = "runtimeArguments")]
    runtime_arguments: Vec<OfficialRuntimeArg>,
    #[serde(default, rename = "environmentVariables")]
    environment_variables: Vec<OfficialEnvVar>,
    #[serde(default, rename = "configSchema")]
    config_schema: Option<Value>,
}

impl OfficialPackage {
    /// A worked example of how to launch this package.
    ///
    /// `uvx` for Python, `npx -y` for Node, and `npx -y` for anything
    /// unrecognised — most of the ecosystem is Node, so it is the least
    /// surprising guess when the registry does not say.
    pub(super) fn to_example_config(&self) -> Value {
        let (command, mut args) = match self.registry_type.as_deref() {
            Some("pypi") => (
                self.runtime_hint.as_deref().unwrap_or("uvx").to_string(),
                Vec::new(),
            ),
            Some("npm") => {
                let command = self.runtime_hint.as_deref().unwrap_or("npx").to_string();
                // `-y` only when the package declares no arguments of its own;
                // a package that does may well be passing its own flags first.
                let args = if self.runtime_arguments.is_empty() {
                    vec!["-y".to_string()]
                } else {
                    Vec::new()
                };
                (command, args)
            }
            _ => (
                self.runtime_hint.as_deref().unwrap_or("npx").to_string(),
                vec!["-y".to_string()],
            ),
        };

        args.extend(
            self.runtime_arguments
                .iter()
                .filter_map(|argument| argument.value.clone()),
        );
        if let Some(identifier) = &self.identifier {
            args.push(identifier.clone());
        }

        serde_json::json!({ "command": command, "args": args })
    }

    /// The package's input schema.
    ///
    /// Built from the declared environment variables when there are any, and
    /// otherwise the schema the registry supplied verbatim.
    pub(super) fn to_config_schema(&self) -> Option<Value> {
        if self.environment_variables.is_empty() {
            return self.config_schema.clone();
        }

        build_schema(
            self.environment_variables
                .iter()
                .map(|variable| SchemaField {
                    name: &variable.name,
                    description: variable.description.as_deref(),
                    is_secret: variable.is_secret == Some(true),
                    is_required: variable.is_required == Some(true),
                }),
        )
    }
}

/// One argument the package is launched with.
#[derive(Debug, Clone, Deserialize)]
struct OfficialRuntimeArg {
    #[serde(default)]
    value: Option<String>,
}

/// One declared environment variable.
#[derive(Debug, Clone, Deserialize)]
struct OfficialEnvVar {
    #[serde(default)]
    name: String,
    #[serde(default)]
    description: Option<String>,
    #[serde(default, rename = "isRequired")]
    is_required: Option<bool>,
    #[serde(default, rename = "isSecret")]
    is_secret: Option<bool>,
}

/// One input, however it was declared.
struct SchemaField<'a> {
    name: &'a str,
    description: Option<&'a str>,
    is_secret: bool,
    is_required: bool,
}

/// Builds an input schema from declared fields.
///
/// Unnamed fields are skipped — an input with no name cannot be prompted for
/// and cannot be sent. `None` when nothing usable is left.
fn build_schema<'a>(fields: impl Iterator<Item = SchemaField<'a>> + Clone) -> Option<Value> {
    let mut properties = Map::new();
    let mut required = Vec::new();

    for field in fields {
        if field.name.is_empty() {
            continue;
        }

        let mut property = Map::new();
        if let Some(description) = field.description {
            property.insert("description".into(), Value::String(description.to_string()));
        }
        if field.is_secret {
            // The marker an install form reads to render a masked input.
            property.insert("x-secret".into(), Value::Bool(true));
        }

        properties.insert(field.name.to_string(), Value::Object(property));
        if field.is_required {
            required.push(Value::String(field.name.to_string()));
        }
    }

    if properties.is_empty() {
        return None;
    }

    let mut schema = Map::new();
    schema.insert("properties".into(), Value::Object(properties));
    if !required.is_empty() {
        schema.insert("required".into(), Value::Array(required));
    }

    Some(Value::Object(schema))
}

//! The official `modelcontextprotocol/registry` catalog.
//!
//! `GET /v0/servers` lists; `GET /v0/servers/{name}/versions` details — the
//! registry has no single-server endpoint, so a detail lookup reads the version
//! list and takes the newest.
//!
//! # Pages over cursors
//!
//! The registry pages by opaque cursor: each response carries the token for the
//! next page, or none when the results end. Callers here ask for numbered
//! pages, so the adapter keeps a map from page to the cursor that produced it.
//!
//! Asking for page N with a warm map costs one request. With a cold map — after
//! a restart, or a link straight to page N — the adapter walks forward from
//! page one, filling the map as it goes. The walk stops at
//! [`MAX_CURSOR_WALK_PAGES`] rather than fan one request into hundreds; a
//! caller that needs to go deeper should page sequentially, which builds the
//! map naturally.
//!
//! The walk also consults the stored response cache before making a request,
//! so a cold in-memory map after a restart does not mean a cold network.
//!
//! # The page count is a bound, not a total
//!
//! Knowing the true total would mean walking the whole cursor chain, which is
//! the cost this design exists to avoid. The adapter reports one page beyond
//! the current one while more results exist, which is what a caller needs to
//! decide whether to offer a "next" control.

mod types;

use std::collections::HashMap;
use std::time::Duration;

use parking_lot::Mutex;
use serde_json::Value;

use self::types::{OfficialListResponse, OfficialServer};
use super::encode::encode_path_segment;
use super::shared::{MAX_ERROR_BODY_BYTES, cache, truncate};
use super::types::non_blank_env;
use crate::error::{Error, Result};
use crate::registry::Store;
use tinymcp_bus::{McpRegistryAuthConfig, RegistryServerDetail, RegistryServerSummary};

/// Where the registry lives when nothing overrides it.
const DEFAULT_BASE: &str = "https://registry.modelcontextprotocol.io";

/// How long to wait on the registry.
const TIMEOUT: Duration = Duration::from_secs(15);

/// How far the adapter will walk to reach a deep page with a cold map.
///
/// At fifty rows a page this reaches the two-thousand-five-hundredth result.
/// Past that a single request would fan into hundreds upstream, which is a
/// denial of service aimed at someone else.
const MAX_CURSOR_WALK_PAGES: u32 = 50;

/// The map from page to the cursor that produced it.
type CursorCache = Mutex<HashMap<(String, u32, u32), String>>;

/// The official catalog adapter.
#[derive(Debug)]
pub struct McpOfficialRegistry {
    http: reqwest::Client,
}

impl McpOfficialRegistry {
    /// Builds the adapter.
    ///
    /// # Errors
    ///
    /// Returns [`Error::ClientBuild`] when the HTTP client cannot be built.
    pub fn new() -> Result<Self> {
        let http = reqwest::Client::builder()
            .timeout(TIMEOUT)
            .build()
            .map_err(|source| Error::ClientBuild {
                source: Box::new(source.without_url()),
            })?;

        Ok(Self { http })
    }

    /// Searches the catalog.
    ///
    /// # Errors
    ///
    /// Returns [`Error::MalformedResponse`] when a deep page is asked for with
    /// a cold map, plus whatever the upstream returns.
    pub(super) async fn search(
        &self,
        store: &Store,
        auth: &McpRegistryAuthConfig,
        cursors: &CursorCache,
        query: &str,
        page: u32,
        page_size: u32,
    ) -> Result<(Vec<RegistryServerSummary>, u32)> {
        let cache_key = search_cache_key(query, page, page_size);

        if let Ok(Some(cached)) = store.cached(&cache_key)
            && let Ok(parsed) = serde_json::from_str::<OfficialListResponse>(&cached)
        {
            tracing::debug!(page, page_size, "official search cache hit");
            let total_pages = page_bound(page, parsed.next_cursor().is_some());
            if let Some(cursor) = parsed.next_cursor() {
                remember_cursor(cursors, query, page_size, page, cursor.to_string());
            }
            return Ok((parsed.into_summaries(), total_pages));
        }

        let cursor = match page {
            1 => None,
            _ => match recall_cursor(cursors, query, page_size, page - 1) {
                Some(cursor) => Some(cursor),
                None => {
                    match self
                        .walk_to(store, auth, cursors, query, page_size, page)
                        .await?
                    {
                        Some(cursor) => Some(cursor),
                        // The chain ended before reaching the page asked for.
                        // An empty result reporting this page as the last is
                        // what stops a caller paging further.
                        None => return Ok((Vec::new(), page)),
                    }
                }
            },
        };

        let body = self
            .fetch_page(auth, query, page_size, cursor.as_deref())
            .await?;
        let parsed: OfficialListResponse = serde_json::from_str(&body)
            .map_err(|error| Error::malformed(format!("official list response: {error}")))?;

        let next_cursor = parsed.next_cursor().map(ToString::to_string);
        if let Some(cursor) = next_cursor.clone() {
            remember_cursor(cursors, query, page_size, page, cursor);
        }
        cache(store, &cache_key, &body);

        Ok((
            parsed.into_summaries(),
            page_bound(page, next_cursor.is_some()),
        ))
    }

    /// Fetches one server's detail.
    ///
    /// # Errors
    ///
    /// Returns [`Error::UnknownServer`] when the registry lists no version of
    /// it, plus whatever the upstream returns.
    pub(super) async fn get(
        &self,
        store: &Store,
        auth: &McpRegistryAuthConfig,
        qualified_name: &str,
    ) -> Result<RegistryServerDetail> {
        let cache_key = format!("mcp_official:detail:{qualified_name}");

        if let Ok(Some(cached)) = store.cached(&cache_key)
            && let Ok(server) = serde_json::from_str::<OfficialServer>(&cached)
        {
            tracing::debug!(qualified_name, "official detail cache hit");
            return Ok(server.into_detail());
        }

        let url = format!(
            "{}/v0/servers/{}/versions",
            base_url(auth),
            encode_path_segment(qualified_name)
        );
        let body = self.send(self.request(auth, &url), &url).await?;

        let document: Value = serde_json::from_str(&body)
            .map_err(|error| Error::malformed(format!("official versions response: {error}")))?;

        // The versions endpoint answers with the same envelope array as the
        // list endpoint; the newest version leads it.
        let newest = document
            .pointer("/servers/0/server")
            .ok_or_else(|| Error::UnknownServer {
                server: qualified_name.to_string(),
            })?;

        // Cached as the inner object, which is what the hit path above reads.
        cache(store, &cache_key, &newest.to_string());

        let server: OfficialServer = serde_json::from_value(newest.clone())
            .map_err(|error| Error::malformed(format!("official server record: {error}")))?;

        Ok(server.into_detail())
    }

    /// Walks forward from page one until the cursor for `target` is known.
    ///
    /// Returns the cursor to send for `target`, or `None` when the chain ran
    /// out first. Fills the map as it goes, so the pages after this one cost
    /// one request each.
    async fn walk_to(
        &self,
        store: &Store,
        auth: &McpRegistryAuthConfig,
        cursors: &CursorCache,
        query: &str,
        page_size: u32,
        target: u32,
    ) -> Result<Option<String>> {
        if target <= 1 {
            return Ok(None);
        }
        if target > MAX_CURSOR_WALK_PAGES {
            return Err(Error::malformed(format!(
                "page {target} is beyond the {MAX_CURSOR_WALK_PAGES} this registry will walk to; \
                 page sequentially to reach it"
            )));
        }

        tracing::debug!(target, page_size, "walking the official registry cursors");

        let mut cursor: Option<String> = None;
        for page in 1..target {
            let cache_key = search_cache_key(query, page, page_size);

            // The stored cache first: after a restart the in-memory map is
            // empty but a previous run's page bodies may still be on disk, and
            // using them removes network calls that have nothing to do with
            // what the network currently holds.
            let body = if let Ok(Some(body)) = store.cached(&cache_key) {
                body
            } else {
                let body = self
                    .fetch_page(auth, query, page_size, cursor.as_deref())
                    .await?;
                cache(store, &cache_key, &body);
                body
            };

            let parsed: OfficialListResponse = serde_json::from_str(&body)
                .map_err(|error| Error::malformed(format!("official list response: {error}")))?;

            match parsed.next_cursor() {
                Some(next) => {
                    remember_cursor(cursors, query, page_size, page, next.to_string());
                    cursor = Some(next.to_string());
                }
                None => return Ok(None),
            }
        }

        Ok(cursor)
    }

    /// Fetches one page.
    async fn fetch_page(
        &self,
        auth: &McpRegistryAuthConfig,
        query: &str,
        limit: u32,
        cursor: Option<&str>,
    ) -> Result<String> {
        // The query is what a user typed. Its presence and length are logged;
        // its text is not, so a search does not end up in a log aggregator.
        tracing::debug!(
            has_query = !query.is_empty(),
            query_length = query.len(),
            limit,
            has_cursor = cursor.is_some(),
            "fetching an official registry page"
        );

        let url = format!("{}/v0/servers", base_url(auth));
        let mut request = self
            .request(auth, &url)
            .query(&[("limit", limit.to_string())]);
        if !query.is_empty() {
            request = request.query(&[("search", query)]);
        }
        if let Some(cursor) = cursor {
            request = request.query(&[("cursor", cursor)]);
        }

        self.send(request, &url).await
    }

    /// A request carrying the accept header and any configured token.
    fn request(&self, auth: &McpRegistryAuthConfig, url: &str) -> reqwest::RequestBuilder {
        let request = self.http.get(url).header("Accept", "application/json");
        match auth_token(auth) {
            Some(token) => request.bearer_auth(token),
            None => request,
        }
    }

    /// Sends a request and returns its body, judging the status first.
    async fn send(&self, request: reqwest::RequestBuilder, url: &str) -> Result<String> {
        let response = request
            .send()
            .await
            .map_err(|error| Error::transport(url, error))?;

        let status = response.status();
        let body = response
            .text()
            .await
            .map_err(|error| Error::transport(url, error))?;

        if !status.is_success() {
            return Err(Error::Http {
                endpoint: crate::redact_endpoint(url),
                status: status.as_u16(),
                body: truncate(&body, MAX_ERROR_BODY_BYTES),
            });
        }

        Ok(body)
    }
}

/// The cache key for one page of one search.
fn search_cache_key(query: &str, page: u32, page_size: u32) -> String {
    format!("mcp_official:search:{query}:{page}:{page_size}")
}

/// Records which cursor produced a page.
fn remember_cursor(cursors: &CursorCache, query: &str, page_size: u32, page: u32, cursor: String) {
    cursors
        .lock()
        .insert((query.to_string(), page_size, page), cursor);
}

/// Recalls which cursor produced a page.
fn recall_cursor(cursors: &CursorCache, query: &str, page_size: u32, page: u32) -> Option<String> {
    cursors
        .lock()
        .get(&(query.to_string(), page_size, page))
        .cloned()
}

/// The best-effort page count. See the module note.
fn page_bound(page: u32, has_next: bool) -> u32 {
    if has_next {
        page.saturating_add(1)
    } else {
        page
    }
}

/// The effective registry base: configuration first, then the environment,
/// then the default.
fn base_url(auth: &McpRegistryAuthConfig) -> String {
    auth.mcp_official_base
        .clone()
        .filter(|base| !base.trim().is_empty())
        .or_else(|| non_blank_env("MCP_OFFICIAL_REGISTRY_BASE"))
        .unwrap_or_else(|| DEFAULT_BASE.to_string())
}

/// The effective registry token: configuration first, then the environment.
fn auth_token(auth: &McpRegistryAuthConfig) -> Option<String> {
    auth.mcp_official_token
        .clone()
        .filter(|token| !token.trim().is_empty())
        .or_else(|| non_blank_env("MCP_OFFICIAL_REGISTRY_TOKEN"))
}

